$labId='win-nwf-tcp-http'; $labRoot='C:\LabEx\Labs\win-nwf-tcp-http'
function Assert-FndWorkspace {
  $expected='C:\LabEx\Labs\'+$labId
  if([IO.Path]::GetFullPath($labRoot) -ne $expected){throw 'Unexpected lab root'}
  foreach($path in @('C:\LabEx','C:\LabEx\Labs',$labRoot)){
    if((Test-Path -LiteralPath $path) -and ((Get-Item -LiteralPath $path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Reparse path refused'}
  }
  if((Test-Path -LiteralPath $labRoot) -and @(Get-ChildItem -LiteralPath $labRoot -Force -Recurse | Where-Object {$_.Attributes -band [IO.FileAttributes]::ReparsePoint}).Count){throw 'Reparse item refused'}
}
Assert-FndWorkspace
New-Item -ItemType Directory -Path $labRoot -Force | Out-Null
function Test-NwfConnect([int]$port){
  $client=[Net.Sockets.TcpClient]::new()
  try{
    $pending=$client.BeginConnect([Net.IPAddress]::Loopback,$port,$null,$null)
    try{if(-not $pending.AsyncWaitHandle.WaitOne(1500)){return $false};$client.EndConnect($pending);return $client.Connected}
    catch{return $false}finally{$pending.AsyncWaitHandle.Close()}
  }finally{$client.Dispose()}
}
function Get-NwfTcpExperiment {
  $listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,0)
  $accepted=$null
  try{
    $listener.Start();$port=([Net.IPEndPoint]$listener.LocalEndpoint).Port
    $open=Test-NwfConnect $port
    if(-not $open){throw 'Loopback connection failed'}
    $accepted=$listener.AcceptTcpClient();$accepted.Dispose();$accepted=$null
    $listener.Stop()
    $closed=Test-NwfConnect $port
    if($closed){throw 'Port was reused; rerun experiment'}
    [pscustomobject]@{Address='127.0.0.1';OpenReachable=$open;ClosedReachable=$closed;Transport='TCP';Scope='LoopbackOnly'}
  }finally{if($accepted){$accepted.Dispose()};$listener.Stop()}
}
$data=Get-NwfTcpExperiment
[pscustomobject]@{Schema=1;LabId=$labId;Computer=$env:COMPUTERNAME;CollectedAtUtc=[DateTimeOffset]::UtcNow.ToString('o');Data=$data} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $labRoot 'step1.json') -Encoding UTF8
Write-Output 'Da ghi step1.json; xem Data trong thu muc bai.'

